#!/usr/bin/env node
// ============================================================
// [QuickStart 2026-07-24] Compose the BUNDLED template shelf and mirror it into the
// Oqtane package payload.
//
// The bundled shelf = what a fresh install finds in the Template Gallery before it ever
// talks to the network:
//   • Samples/FormTemplates/QuickStart/*.json      — free starters (premium:false)
//   • the BUNDLED premium starters from the gallery source, named by
//     tools/gallery/gallery-exclude.json → bundledSlugs (generated by build-gallery.mjs)
//
// DNN reads both folders at pack time (BuildPackage-DNN.ps1). Oqtane ships whatever sits in
// MegaForm.Oqtane.Server/wwwroot/Modules/MegaForm/Templates, which is a committed artifact —
// so it has to be regenerated here or the two platforms drift.
//
// Run order matters: build-gallery.mjs first (it writes bundledSlugs), then this.
//
// Usage:  node tools/gallery/sync-bundled-templates.mjs [--check]
// ============================================================
import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const CHECK = process.argv.includes('--check');
const REPO_ROOT = resolve(join(dirname(fileURLToPath(import.meta.url)), '..', '..'));
const QUICKSTART = join(REPO_ROOT, 'Samples', 'FormTemplates', 'QuickStart');
const PREMIUM_SRC = join(REPO_ROOT, 'Samples', 'FormTemplates', 'Premium', 'DONEE');
const EXCLUDE_JSON = join(REPO_ROOT, 'tools', 'gallery', 'gallery-exclude.json');
const OQTANE_OUT = join(REPO_ROOT, 'MegaForm.Oqtane.Server', 'wwwroot', 'Modules', 'MegaForm', 'Templates');

function fail(msg) { console.error('FAILED: ' + msg); process.exit(1); }

if (!existsSync(QUICKSTART)) fail('QuickStart folder missing — run: node tools/gallery/build-quickstart.mjs');
if (!existsSync(EXCLUDE_JSON)) fail('gallery-exclude.json missing — run: node tools/gallery/build-gallery.mjs --out <gallery-repo>');

const bundledSlugs = new Set((JSON.parse(readFileSync(EXCLUDE_JSON, 'utf8')).bundledSlugs || []).map((s) => String(s).toLowerCase()));
if (!bundledSlugs.size) fail('gallery-exclude.json lists no bundledSlugs');

// ── collect ───────────────────────────────────────────────
const picked = [];   // { name, data, kind }
const seenSlug = new Map();

function add(dir, file, kind) {
  const raw = readFileSync(join(dir, file), 'utf8');
  let doc; try { doc = JSON.parse(raw); } catch (e) { fail(`${file}: invalid JSON — ${e.message}`); }
  const slug = String(doc.slug || doc.Slug || '').trim().toLowerCase();
  if (!slug) fail(`${file}: no slug`);
  // Two bundled templates sharing a slug means one of them is unreachable in the catalog.
  if (seenSlug.has(slug)) fail(`duplicate bundled slug "${slug}": ${file} vs ${seenSlug.get(slug)}`);
  seenSlug.set(slug, file);
  picked.push({ name: file, data: raw, kind, slug });
}

for (const f of readdirSync(QUICKSTART).filter((x) => x.toLowerCase().endsWith('.json')).sort()) add(QUICKSTART, f, 'quickstart');

const premiumFound = new Set();
for (const f of readdirSync(PREMIUM_SRC).filter((x) => x.toLowerCase().endsWith('.json')).sort()) {
  const doc = JSON.parse(readFileSync(join(PREMIUM_SRC, f), 'utf8'));
  const slug = String(doc.slug || doc.Slug || '').trim().toLowerCase();
  if (!bundledSlugs.has(slug)) continue;
  premiumFound.add(slug);
  add(PREMIUM_SRC, f, 'premium');
}
for (const s of bundledSlugs) if (!premiumFound.has(s)) fail(`bundledSlugs names "${s}" but no template in ${PREMIUM_SRC} has that slug`);

// ── write ─────────────────────────────────────────────────
const existing = existsSync(OQTANE_OUT) ? readdirSync(OQTANE_OUT).filter((f) => f.toLowerCase().endsWith('.json')).sort() : [];
const wanted = picked.map((p) => p.name).sort();
const drift = existing.length !== wanted.length || existing.some((f, i) => f !== wanted[i]);

if (CHECK) {
  console.log('Bundled shelf CHECK — Oqtane payload ' + (drift ? 'OUT OF SYNC' : 'in sync'));
  if (drift) {
    console.log('  extra  : ' + existing.filter((f) => !wanted.includes(f)).join(', '));
    console.log('  missing: ' + wanted.filter((f) => !existing.includes(f)).join(', '));
    process.exit(1);
  }
} else {
  mkdirSync(OQTANE_OUT, { recursive: true });
  for (const stale of existing) rmSync(join(OQTANE_OUT, stale), { force: true });
  for (const p of picked) writeFileSync(join(OQTANE_OUT, p.name), p.data, 'utf8');
}

const q = picked.filter((p) => p.kind === 'quickstart');
const pr = picked.filter((p) => p.kind === 'premium');
const kb = (n) => (n / 1024).toFixed(1) + ' KB';
console.log('Bundled shelf -> ' + OQTANE_OUT);
console.log('  quick-start : ' + q.length + ' (' + kb(q.reduce((n, x) => n + Buffer.byteLength(x.data), 0)) + ', premium:false — usable on trial)');
console.log('  premium     : ' + pr.length + ' (' + kb(pr.reduce((n, x) => n + Buffer.byteLength(x.data), 0)) + ') — ' + pr.map((x) => x.slug).join(', '));
console.log('  total       : ' + picked.length + ' templates, ' + kb(picked.reduce((n, x) => n + Buffer.byteLength(x.data), 0)));
